sp_widget.css:
.tree-horizontal {
   display: flex;
   flex-direction: column;
   align-items: center;
   margin: 30px;
   position: relative;
 }

 .children-list-horizontal {
   display: flex;
   flex-direction: row;
   justify-content: center;
   gap: 30px;
   margin-top: 30px;
   position: relative;
 }

 /* Linha horizontal que conecta filhos */
 .children-list-horizontal::before {
   content: '';
   position: absolute;
   top: 0;
   left: 0;
   right: 0;
   height: 2px;
   background: #555;
   z-index: 0;
 }

 /* Pai */
 .parent-node {
   min-width: 140px;
   height: 70px;
   background-color: #e0e0e0;
   border: 2px solid #555;
   border-radius: 6px;
   font-weight: bold;
   font-family: 'Roboto Flex', sans-serif;
   text-align: center;
   line-height: 70px;
   padding: 0 15px;
   white-space: nowrap;
   overflow: visible !important;
   text-overflow: ellipsis;
   position: relative;
   display: inline-block;
 }

 /* Linha vertical saindo do pai */
 .parent-node::after {
   content: '';
   position: absolute;
   bottom: -30px;
   left: 50%;
   width: 2px;
   height: 30px;
   background: #555;
   transform: translateX(-50%);
   z-index: 10;
 }

 /* Filho */
 .child-node {
   min-width: 110px;
   height: 55px;
   background-color: #f8f8f8;
   border: 1px solid #888;
   border-radius: 6px;
   font-family: 'Roboto Flex', sans-serif;
   text-align: center;
   line-height: 55px;
   font-size: 14px;
   padding: 0 10px;
   white-space: nowrap;
   overflow: visible !important;
   text-overflow: ellipsis;
   display: inline-block;
   position: relative;
 }

 /* Linha vertical saindo do filho até a linha horizontal */
 .child-node::before {
   content: '';
   position: absolute;
   top: -30px;
   left: 50%;
   width: 2px;
   height: 30px;
   background: #555;
   transform: translateX(-50%);
   z-index: 10;
 }

 /* Tooltip geral */
 .tooltip-container {
   position: relative;
   display: inline-block;
   cursor: help;
   overflow: visible;
 }

 .tooltip-text {
   visibility: hidden;
   width: max-content;
   max-width: 300px;
   background-color: #333;
   color: #fff;
   text-align: center;
   border-radius: 6px;
   padding: 5px 8px;
   position: absolute;
   z-index: 1000;
   bottom: 125%;
   left: 50%;
   transform: translateX(-50%);
   opacity: 0;
   transition: opacity 0.3s;
   font-size: 12px;
   white-space: normal;
 }

 .tooltip-container:hover .tooltip-text {
   visibility: visible;
   opacity: 1;
 }

 /* Tooltip usuários (balão à direita) */
 .tooltip-users {
  	line-height: 2;
 	padding: 6px 8px;
 	font-size: 10px;
   visibility: hidden;
   background-color: #293273;
   color: white;
   padding: 6px 10px;
   border-radius: 6px;
   position: absolute;
   top: 60%;
   left: 105%;
   transform: translateY(-50%);
   box-shadow: 0 0 8px rgba(0,0,0,0.7);
   font-size: 10px;
   white-space: nowrap;
   z-index: 1100;
   opacity: 0;
   transition: opacity 0.3s;
   text-align: left;
   pointer-events: none;
   /* largura automática para evitar quebra */
   max-width: none;
   overflow: visible;
   /* removida altura e overflow-y para eliminar barra */
 }

 .tooltip-container:hover .tooltip-users {
   visibility: visible;
   opacity: 1;
 }

sp_widget.link:
function link(scope, element, attrs, controller) {
angular.module('sn.$sp').directive('orgChart', function($compile) {
  return {
    scope: {
      node: '='
    },
    templateUrl: 'org-chart-template',
    link: function(scope, element) {
      $compile(element.contents())(scope);
    }
  };
});

}

sp_widget.script:
(function() {
   var departments = [];
   var gr = new GlideRecord('cmn_department');
   gr.query();

   while (gr.next()) {
     departments.push({
       sys_id: gr.sys_id.toString(),
       name: gr.name.toString(),
       sigla: gr.getValue('u_sigla_unidade') || '',
       parent_sys_id: gr.getValue('u_nome_unidade_superior') ? gr.getValue('u_nome_unidade_superior').trim() : '',
       parentName: gr.getDisplayValue('u_nome_unidade_superior'),
       users: [] // Inicializa array para usuários
     });
   }

   // Buscar usuários por departamento
   var userGR = new GlideRecord('sys_user');
   userGR.query();

   var usersByDepartment = {};
   while(userGR.next()) {
     var dep = userGR.getValue('department');
     if(dep) {
       if(!usersByDepartment[dep])
         usersByDepartment[dep] = [];
       usersByDepartment[dep].push(userGR.getDisplayValue('name'));
     }
   }

   // Montar mapa e árvore
   var map = {};
   departments.forEach(function(dep) {
     map[dep.sys_id] = Object.assign({}, dep, { children: [], users: [] });
   });

   departments.forEach(function(dep) {
     // adiciona usuários do departamento se existirem
     if(usersByDepartment[dep.sys_id]) {
       map[dep.sys_id].users = usersByDepartment[dep.sys_id];
     }
   });

   var roots = [];

   departments.forEach(function(dep) {
     if(dep.parent_sys_id && map[dep.parent_sys_id]) {
       map[dep.parent_sys_id].children.push(map[dep.sys_id]);
     } else {
       roots.push(map[dep.sys_id]);
     }
   });

   // Filtrar roots para mostrar só nós com pai ou filhos
   roots = roots.filter(function(node) {
     var hasParent = !!node.parent_sys_id;
     var hasChildren = node.children && node.children.length > 0;
     return hasParent || hasChildren;
   });

   // Ordenar filhos por nome
   Object.values(map).forEach(function(node) {
     node.children.sort(function(a,b){
       return a.name.localeCompare(b.name);
     });
   });

   data.roots = roots;
 })();
